import { useEffect, useState } from "react";

export default function Reviews() {
  const [analytics, setAnalytics] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  /* ================= FETCH ANALYTICS ================= */
  useEffect(() => {
    const fetchAnalytics = async () => {
      try {
        const res = await fetch(
          "http://localhost:5001/admin/reviews/analytics"
        );

        if (!res.ok) throw new Error("Failed to fetch analytics");

        const data = await res.json();
        setAnalytics(data);
      } catch (err) {
        console.error(err);
        setError("Unable to load review analytics");
      } finally {
        setLoading(false);
      }
    };

    fetchAnalytics();
  }, []);

  if (loading) {
    return (
      <div className="p-10 text-gray-400">
        Loading review insights…
      </div>
    );
  }

  if (error) {
    return (
      <div className="p-10 text-red-400">
        {error}
      </div>
    );
  }

  if (!analytics) return null;

  return (
    <div className="p-10 text-white">
      {/* ================= HEADER ================= */}
      <h1 className="text-4xl font-bold text-yellow-400 mb-4">
        Customer Voice Intelligence
      </h1>
      <p className="text-gray-400 max-w-3xl mb-12">
        This dashboard summarizes how customers feel about BodyZeal Fitworks.
        Reviews are auto-published using safety rules, so only real insights
        matter here — not manual approvals.
      </p>

      {/* ================= KPI GRID ================= */}
      <div className="grid md:grid-cols-4 gap-6 mb-14">
        {/* AVG RATING */}
        <InsightCard
          title="Average Rating"
          value={`${analytics.avgRating.toFixed(1)} ★`}
          desc="Overall customer satisfaction"
        />

        {/* TOTAL REVIEWS */}
        <InsightCard
          title="Total Reviews"
          value={analytics.totalReviews}
          desc="Real user voices collected"
        />

        {/* NEGATIVE SIGNAL */}
        <InsightCard
          title="Negative Signals"
          value={`${analytics.flaggedReviews}`}
          desc="Low ratings & complaint patterns"
          danger
        />

        {/* NPS */}
        <InsightCard
          title="Customer Loyalty (NPS)"
          value={`${analytics.nps}%`}
          desc="Likelihood of referrals"
        />
      </div>

      {/* ================= INTERPRETATION ================= */}
      <div className="grid md:grid-cols-2 gap-8">
        {/* CUSTOMER FEELING */}
        <InsightPanel title="How users feel">
          {analytics.avgRating >= 4 ? (
            <p className="text-green-400">
              Customers are highly satisfied. The brand is trusted
              and experiences are mostly positive.
            </p>
          ) : analytics.avgRating >= 3 ? (
            <p className="text-yellow-400">
              Customers feel neutral to good. There is room to improve
              service consistency and engagement.
            </p>
          ) : (
            <p className="text-red-400">
              Customers are unhappy. Immediate action is required
              to improve experience and trust.
            </p>
          )}
        </InsightPanel>

        {/* WHAT TO IMPROVE */}
        <InsightPanel title="What needs improvement">
          {analytics.flaggedReviews === 0 ? (
            <p className="text-green-400">
              No major complaints detected. Maintain current standards.
            </p>
          ) : (
            <ul className="list-disc ml-5 text-gray-300 space-y-2">
              <li>Service quality issues</li>
              <li>Staff interaction concerns</li>
              <li>Expectation mismatch in plans or pricing</li>
              <li>Facilities or cleanliness feedback</li>
            </ul>
          )}
        </InsightPanel>
      </div>

      {/* ================= FOOTER NOTE ================= */}
      <div className="mt-16 text-sm text-gray-500 max-w-3xl">
        Reviews are auto-moderated using safety filters:
        abusive language, spam, excessive links, emojis and low ratings
        are flagged automatically. This ensures authenticity while
        reducing admin workload by over 80%.
      </div>
    </div>
  );
}

/* ================= REUSABLE COMPONENTS ================= */

function InsightCard({ title, value, desc, danger }) {
  return (
    <div
      className={`bg-gradient-to-br from-[#0b0b0b] to-[#111]
      border ${danger ? "border-red-500/40" : "border-yellow-500/30"}
      rounded-3xl p-8 shadow-xl`}
    >
      <p className="text-gray-400 text-sm tracking-wide">
        {title}
      </p>
      <p
        className={`text-4xl font-bold mt-4 ${
          danger ? "text-red-400" : "text-yellow-400"
        }`}
      >
        {value}
      </p>
      <p className="text-gray-500 text-sm mt-3">
        {desc}
      </p>
    </div>
  );
}

function InsightPanel({ title, children }) {
  return (
    <div
      className="bg-gradient-to-br from-[#0b0b0b] to-[#111]
      border border-yellow-500/30 rounded-3xl p-8 shadow-xl"
    >
      <h2 className="text-xl font-semibold text-yellow-400 mb-4">
        {title}
      </h2>
      {children}
    </div>
  );
}
